// Reads Config: one item per doctor and per window of 15 days at most, the most Doctolib serves at once.
const cfg = $('Config').first().json;
const day = /^\d{4}-\d{2}-\d{2}$/;
if (!day.test(cfg.from ?? '') || !day.test(cfg.to ?? '')) throw new Error('Config: set from and to as YYYY-MM-DD.');
if (!String(cfg.notify_to ?? '').includes('@')) throw new Error('Config: set notify_to to the email address that gets the confirmation.');
const doctors = String(cfg.doctors ?? '').split(/[\s,]+/).filter(Boolean);
if (!doctors.length) throw new Error('Config: add the Doctolib link of at least one doctor to doctors, one per line.');

const today = DateTime.now().setZone('Europe/Paris').toISODate();
const from = cfg.from > today ? cfg.from : today;
if (cfg.to < from) return []; // the dates are over

const out = [];
for (const link of doctors) {
  // The Code node has no URL class: the link is split by hand.
  const [base, query = ''] = String(link).trim().split('#')[0].split('?');
  const params = Object.fromEntries(query.split('&').filter(Boolean).map((kv) => kv.split('=').map(decodeURIComponent)));
  const path = base.replace(/^https?:\/\/[^/]+\/?/, '').replace(/\/booking(\/.*)?$/, '').replace(/\/+$/, '');
  const pid = params.placeId ?? params.pid;
  const motive = params['motiveIds[]'] ?? params['vmids[]'];
  if (!pid || !motive)
    throw new Error(`Config: this link does not give the place and the type of visit: ${link}. On doctolib.fr, click Book, choose both, then copy the address of the page that shows the dates.`);
  for (let d = DateTime.fromISO(from); d.toISODate() <= cfg.to; d = d.plus({ days: 15 })) {
    const left = DateTime.fromISO(cfg.to).diff(d, 'days').days + 1;
    out.push({ json: { profile_path: `${path}?pid=${pid}`, motive_id: Number(motive), start_date: d.toISODate(), days: Math.min(15, left) } });
  }
}
return out;

// The earliest free slot inside the dates, weekdays and hours of Config. None: the run stops here.
const cfg = $('Config').first().json;
const NAMES = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
const weekdays = String(cfg.weekdays ?? '').toLowerCase().split(',').map((s) => s.trim().slice(0, 3)).filter(Boolean);
const [earliest, latest] = String(cfg.hours ?? '').split('-').map((s) => s.trim());
const asked = $('Doctors').all();

let best = null;
$input.all().forEach((item, i) => {
  const r = item.json.result;
  for (const { slots } of r.availabilities) {
    for (const slot of slots) {
      const t = DateTime.fromISO(slot, { setZone: true });
      const hm = t.toFormat('HH:mm');
      if (t.toISODate() < cfg.from || t.toISODate() > cfg.to) continue;
      if (weekdays.length && !weekdays.includes(NAMES[t.weekday - 1])) continue;
      if (earliest && hm < earliest) continue;
      if (latest && hm > latest) continue;
      if (!best || Date.parse(slot) < Date.parse(best.start_date))
        best = { ...asked[i].json, start_date: slot, practitioner: r.name, motive: r.motive.name };
    }
  }
});
return best ? [{ json: best }] : [];

// An upcoming appointment with one of the doctors means the job is done: the run stops here.
const doctors = new Set($('Doctors').all().map((d) => d.json.profile_path.split('?')[0]));
const mine = $input.first().json.result.appointments.find(
  (a) => !a.canceled && !a.past && doctors.has(String(a.profile_path ?? '').split('?')[0]),
);
return mine ? [] : [{ json: $('Earliest slot').first().json }];
